import { useCallback, useState } from "react";
export const useHidden = () => {
    const [hiddenDatasets, setHiddenDatasets] = useState(new Set());
    const isHidden = useCallback((index) => hiddenDatasets.has(index), [hiddenDatasets]);
    const toggleHidden = useCallback((index) => {
        const hidden = new Set(hiddenDatasets);
        if (hiddenDatasets.has(index)) {
            hidden.delete(index);
        }
        else {
            hidden.add(index);
        }
        setHiddenDatasets(hidden);
    }, [hiddenDatasets, setHiddenDatasets]);
    return { isHidden, toggleHidden };
};
